from typing import List
from textkit.normalize_whitespace import normalize_whitespace

def split_sentences(text: str) -> List[str]:
    if not text:
        return []
    text = normalize_whitespace(text)
    words = text.split()
    if not words:
        return []

    abbreviations = {"Mr.", "Mrs.", "Ms.", "Dr.", "Prof.", "St.", "vs.", "e.g.", "i.e."}
    terminators = ".!?"
    closing_chars = "' ) ]"
    opening_chars = "' ( ["

    sentences = []
    start_idx = 0

    for i in range(len(words) - 1):
        word = words[i]
        next_word = words[i+1]

        is_boundary = False
        if word not in abbreviations:
            core = word.lstrip("'([ ")
            is_initial = len(core) == 2 and core[0].isupper() and core[1] == '.'

            if not is_initial:
                last_term_idx = -1
                for j in range(len(word) - 1, -1, -1):
                    if word[j] in terminators:
                        last_term_idx = j
                        break

                if last_term_idx != -1:
                    suffix = word[last_term_idx + 1:]
                    if all(c in closing_chars for c in suffix):
                        # Check next word start
                        if any(next_word.startswith(c) for c in (opening_chars + "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ")):
                            is_boundary = True

        if is_boundary:
            sentences.append(" ".join(words[start_idx:i+1]))
            start_idx = i + 1

    sentences.append(" ".join(words[start_idx:]))
    return sentences
"}}, "messages": []}
